from contextlib import contextmanager

@contextmanager
def temporary_value(data, key, value):
    old_value = data.get(key)
    had_key = key in data
    data[key] = value
    try:
        yield data
    finally:
        if had_key:
            data[key] = old_value
        else:
            data.pop(key, None)

