class UnitOfWork:
    def __init__(self):
        self.events = []

    def __enter__(self):
        self.events.append("enter")
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type is None:
            self.commit()
        else:
            self.rollback()
        self.events.append("exit")
        return False

    def commit(self):
        self.events.append("commit")

    def rollback(self):
        self.events.append("rollback")


def m02_l010_abstrakcii_s007_invariant_4(action):
    uow = UnitOfWork()
    with uow as opened:
        action(opened)
    return uow.events

