def target_count_sorted(items, target):
    def lower(value):
        left, right = 0, len(items)
        while left < right:
            mid = (left + right) // 2
            if items[mid] < value: left = mid + 1
            else: right = mid
        return left
    def upper(value):
        left, right = 0, len(items)
        while left < right:
            mid = (left + right) // 2
            if items[mid] <= value: left = mid + 1
            else: right = mid
        return left
    return upper(target) - lower(target)

