steps.solution_code:
def redis_get_or_set(redis, key, value):
    cached = redis.get(key)
    if cached is None:
        redis.set(key, value)
        return value
    return cached

checker.test_code:
from solution import redis_get_or_set


def test_redis_get_or_set():
    class Redis:
        def __init__(self): self.data={}
        def get(self,k): return self.data.get(k)
        def set(self,k,v): self.data[k]=v
    r=Redis(); assert redis_get_or_set(r, 'user:1', 'Ann') == 'Ann'
    assert r.data == {'user:1': 'Ann'}

from solution import redis_set_with_ttl


def test_redis_set_with_ttl():
    class Redis:
        def __init__(self): self.calls=[]
        def set(self,k,v): self.calls.append(('set',k,v))
        def expire(self,k,s): self.calls.append(('expire',k,s))
    r=Redis(); assert redis_set_with_ttl(r, 'cache:x', 1, 60) is True
    assert ('expire','cache:x',60) in r.calls

from solution import redis_increment_counter


def test_redis_increment_counter():
    class Redis:
        def __init__(self): self.value=0
        def incr(self,k): self.value += 1; return self.value
    assert redis_increment_counter(Redis(), 'counter:login') == 1

steps.solution_code:
def redis_invalidate_prefix(redis, prefix):
    keys = redis.keys(prefix + '*')
    for key in keys:
        redis.delete(key)
    return len(keys)

checker.test_code:
from solution import redis_invalidate_prefix


def test_redis_invalidate_prefix():
    class Redis:
        def __init__(self): self.deleted=[]
        def keys(self,p): return ['user:1','user:2']
        def delete(self,k): self.deleted.append(k)
    r=Redis(); assert redis_invalidate_prefix(r, 'user:') == 2
    assert r.deleted == ['user:1','user:2']

steps.solution_code:
def redis_allow_request(redis, key, limit, window):
    count = redis.incr(key)
    if count == 1:
        redis.expire(key, window)
    return count <= limit

checker.test_code:
from solution import redis_allow_request


def test_redis_allow_request():
    class Redis:
        def __init__(self): self.count=0; self.ttl=[]
        def incr(self,k): self.count += 1; return self.count
        def expire(self,k,w): self.ttl.append((k,w))
    r=Redis(); assert redis_allow_request(r, 'rate:u1', 2, 60) is True
    assert r.ttl == [('rate:u1',60)]

from solution import redis_try_lock


def test_redis_try_lock():
    class Redis:
        def set(self, key, value, nx=False, ex=None): return nx and ex == 30
    assert redis_try_lock(Redis(), 'lock:job', 'worker-1', 30) is True

