def tcp_sequence_ok(segments):
    expected = 1
    for segment in segments:
        if segment['seq'] != expected:
            return False
        expected += 1
    return True

def http_status_class(status):
    if 200 <= status < 300:
        return 'success'
    if 400 <= status < 500:
        return 'client_error'
    if 500 <= status < 600:
        return 'server_error'
    return 'other'

def build_query_string(params):
    if not params:
        return ''
    parts = [f"{key}={params[key]}" for key in sorted(params)]
    return '?' + '&'.join(parts)

def get_header_case_insensitive(headers, name):
    wanted = name.lower()
    for key, value in headers.items():
        if key.lower() == wanted:
            return value
    return None

def parse_retry_after(headers):
    value = get_header_case_insensitive(headers, "Retry-After")
    if value is None:
        return 0
    try:
        return int(value)
    except ValueError:
        return 0

